using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public sealed class WeatherTools
{
    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";
        using var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        using var doc = JsonDocument.Parse(json);
        var weather = doc.RootElement.GetProperty("current_weather");

        return $"Temperature: {weather.GetProperty("temperature")}°C, " +
               $"Wind: {weather.GetProperty("windspeed")} km/h, " +
               $"Code: {weather.GetProperty("weathercode")}";
    }

    [McpServerTool, Description("Look up coordinates for a city name using geocoding.")]
    public async Task<string> GeocodeCityName(
        IHttpClientFactory httpClientFactory,
        [Description("City name to search for")] string cityName,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(cityName)}&count=1";
        using var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        using var doc = JsonDocument.Parse(json);

        if (!doc.RootElement.TryGetProperty("results", out var results) ||
            results.GetArrayLength() == 0)
        {
            return $"No results found for '{cityName}'.";
        }

        var city = results[0];
        return $"{city.GetProperty("name")}: " +
               $"lat={city.GetProperty("latitude")}, " +
               $"lon={city.GetProperty("longitude")}, " +
               $"country={city.GetProperty("country")}";
    }
}

